import fs from 'node:fs';
import path from 'node:path';
import type { GTOutputFileConfig } from 'generaltranslation';
import { defaultInlineTranslationsModulesDir } from 'generaltranslation/internal';
import { createDiagnosticMessage } from 'generaltranslation/diagnostics';
import {
  getInlineTranslationEntries,
  type InlineTranslationsTable,
} from './loadInlineTranslations';

/** Stale-module cleanup deletes only `.js` files that start with this line. */
export const INLINE_TRANSLATIONS_MODULE_HEADER =
  '// Generated by General Translation from embedded translations. Do not edit.';

const MODULE_EXTENSION = '.js';

const createModuleCollisionDiagnostic = (file: string) =>
  createDiagnosticMessage({
    whatHappened: `Did not overwrite ${file}`,
    why: 'it is not a generated message module',
    fix: 'Set files.gt.inlineTranslations.modulesDir to a directory used only for message modules',
  });
const TEMP_FILE_MARKER = `${MODULE_EXTENSION}.tmp-`;
const STALE_TEMP_FILE_MS = 60 * 60 * 1000;
// Accepts every computed hash (16 lowercase hex characters), stays unique on case-insensitive filesystems, and is a valid identifier suffix.
const MODULE_HASH_PATTERN = /^[0-9a-z_]+$/;

/**
 * Whether a hash gets its own message module. Must match the gt-next SWC
 * plugin's `is_module_hash`.
 */
export function isInlineTranslationsModuleHash(hash: string): boolean {
  return MODULE_HASH_PATTERN.test(hash);
}

export function getInlineTranslationsModuleFile(
  dir: string,
  hash: string
): string {
  return path.join(dir, `${hash}${MODULE_EXTENSION}`);
}

/** Absolute `files.gt.inlineTranslations.modulesDir`. */
export function resolveInlineTranslationsModulesDir(
  gtFiles: GTOutputFileConfig | undefined,
  root: string = process.cwd()
): string {
  return path.resolve(
    root,
    gtFiles?.inlineTranslations?.modulesDir ??
      defaultInlineTranslationsModulesDir
  );
}

/**
 * The module source for a message,
 * `export default (locale) => locale === "fr" ? … : undefined;`, or undefined
 * when no embedded locale translates the hash.
 */
export function renderInlineTranslationsModule(
  table: InlineTranslationsTable,
  hash: string
): string | undefined {
  const entries = getInlineTranslationEntries(table, hash);
  if (entries.length === 0) return undefined;
  const body = entries.reduceRight(
    (alternate, [locale, translation]) =>
      `locale === ${JSON.stringify(locale)} ? ${JSON.stringify(translation)} : ${alternate}`,
    'undefined'
  );
  return `${INLINE_TRANSLATIONS_MODULE_HEADER}\nexport default (locale) => ${body};\n`;
}

/** The module source of every message hash that gets a module, by hash. */
export function renderInlineTranslationsModules(
  table: InlineTranslationsTable | undefined
): Map<string, string> {
  const modules = new Map<string, string>();
  if (!table) return modules;
  for (const translations of Object.values(table)) {
    for (const hash of Object.keys(translations)) {
      if (modules.has(hash) || !isInlineTranslationsModuleHash(hash)) continue;
      const source = renderInlineTranslationsModule(table, hash);
      if (source) modules.set(hash, source);
    }
  }
  return modules;
}

/**
 * Write `modules` into `dir`, rewriting only files whose contents changed, and
 * delete generated modules (files starting with the header) for other hashes.
 */
export function writeInlineTranslationsModules(
  dir: string,
  modules: ReadonlyMap<string, string>
): { written: number; removed: number } {
  fs.mkdirSync(dir, { recursive: true });
  let written = 0;
  for (const [hash, source] of modules) {
    if (
      writeFileIfChanged(getInlineTranslationsModuleFile(dir, hash), source)
    ) {
      written++;
    }
  }
  return { written, removed: removeStaleModules(dir, modules) };
}

// Several build processes may write at once, so readers only see complete files
function writeFileIfChanged(file: string, source: string): boolean {
  const existing = readFileIfExists(file);
  if (existing === source) return false;
  if (
    existing !== undefined &&
    !existing.startsWith(INLINE_TRANSLATIONS_MODULE_HEADER)
  ) {
    throw new Error(createModuleCollisionDiagnostic(file));
  }
  const temp = `${file}.tmp-${process.pid}-${Math.random().toString(36).slice(2)}`;
  fs.writeFileSync(temp, source);
  try {
    fs.renameSync(temp, file);
  } finally {
    fs.rmSync(temp, { force: true });
  }
  return true;
}

function removeStaleModules(
  dir: string,
  keep: ReadonlyMap<string, string>
): number {
  let removed = 0;
  for (const entry of fs.readdirSync(dir)) {
    const file = path.join(dir, entry);
    if (entry.includes(TEMP_FILE_MARKER)) {
      const stat = fs.statSync(file, { throwIfNoEntry: false });
      if (stat && Date.now() - stat.mtimeMs >= STALE_TEMP_FILE_MS) {
        fs.rmSync(file, { force: true });
      }
      continue;
    }
    if (!entry.endsWith(MODULE_EXTENSION)) continue;
    const hash = entry.slice(0, -MODULE_EXTENSION.length);
    if (!isInlineTranslationsModuleHash(hash) || keep.has(hash)) continue;
    if (
      !readFileIfExists(file)?.startsWith(INLINE_TRANSLATIONS_MODULE_HEADER)
    ) {
      continue;
    }
    fs.rmSync(file, { force: true });
    removed++;
  }
  return removed;
}

function readFileIfExists(file: string): string | undefined {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch {
    return undefined;
  }
}
